import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Build current state as a dict for efficient updates
    state_dict = {}
    for _, row in target_state.iterrows():
        oid = row["order_id"]
        state_dict[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders have been touched and their final operation
    touched_orders = set()
    final_op = {}  # order_id -> (op, seq) of last applied event

    # Step 4: Apply events with replay guard
    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        oid = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if oid in state_dict and seq <= state_dict[oid]["last_seq"]:
            continue

        # Mark order as touched
        touched_orders.add(oid)

        # Apply the event
        if op == "D":
            # Delete: remove from state if exists
            if oid in state_dict:
                del state_dict[oid]
            final_op[oid] = ("D", seq)
        elif op in ("I", "U"):
            if oid in state_dict:
                # Update existing
                state_dict[oid]["status"] = status
                # For 'U', NULL amount means keep existing; for 'I', use as-is
                if op == "I" or not pd.isna(amount):
                    state_dict[oid]["amount"] = amount
                state_dict[oid]["last_seq"] = seq
            else:
                # Create new
                state_dict[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            final_op[oid] = (op, seq)

    # Step 5: Build new_state
    new_state_rows = []
    for oid in sorted(state_dict.keys()):
        entry = state_dict[oid]
        new_state_rows.append({
            "order_id": oid,
            "status": entry["status"],
            "amount": entry["amount"],
            "last_seq": entry["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Step 6: Build tombstones
    # Tombstones: orders that had a row in target_state or were created,
    # and whose last applied event is 'D'
    tombstone_rows = []
    for oid in touched_orders:
        if oid in final_op and final_op[oid][0] == "D":
            deleted_seq = final_op[oid][1]
            tombstone_rows.append({
                "order_id": oid,
                "deleted_seq": deleted_seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
